SELECT CAST(COUNT(CASE WHEN p.dod IS NULL THEN 1 END) AS FLOAT) / NULLIF(COUNT(CASE WHEN p.dod IS NOT NULL THEN 1 END), 0) AS survival_ratio, AVG(i.los) AS average_los, STDDEV(i.los) AS standard_deviation_los, CAST(COUNT(CASE WHEN i.los < 7 THEN 1 END) AS FLOAT) / NULLIF(COUNT(i.los), 0) AS los_less_than_7_days_ratio FROM patients p JOIN icustays i ON p.subject_id = i.subject_id WHERE p.gender = 'F' AND p.anchor_age = 40 AND EXTRACT(YEAR FROM CURRENT_DATE) - p.anchor_year BETWEEN 35 AND 45;